function callDllMainOwned(exports, loadAddr, dllMain, log, options = {}) {
  const token = dllMainToken(exports, loadAddr);
  const steps = dllMainSteps(exports, loadAddr, dllMain, log, options);
  let step = steps.next();
  while (!step.done) {
    try {
      const serviced = options.onLoadLibraryYield ? options.onLoadLibraryYield(exports) : false;
      if (serviced && typeof serviced.then === 'function') {
        throw new Error('Asynchronous DLL lookup requires callDllMainAsync');
      }
      step = steps.next(!!serviced);
    } catch (error) { step = steps.throw(error); }
  }
  return finishDllMain(exports, token, loadAddr, options, step.value);
}

steps.text:
function* dllMainSteps(exports, loadAddr, dllMain, log, options = {}) {
  const maxBlocks = typeof options === 'number'
    ? options : (options.maxBlocks == null ? 2000000 : options.maxBlocks);
  const lpReserved = typeof options === 'number'
    ? 0 : (options.lpReserved == null ? 0 : options.lpReserved);
  const reason = typeof options === 'number'
    ? 1 : (options.reason == null ? 1 : options.reason);
  const advanceGuestTime = typeof options === 'number'
    ? null : (typeof options.advanceGuestTime === 'function' ? options.advanceGuestTime : null);
  const memory = exports.memory;
  const dv = new DataView(memory.buffer);
  const imageBase = exports.get_image_base();
  // Worker stacks can live in sparse VirtualAlloc regions far above the PE
  // image. The historical image-base formula only covers the contiguous main
  // mapping and turns such an ESP into a DataView offset beyond linear memory.
  // The shared helper uses the interpreter's mapper when available and its
  // packed-page JS twin for small loader mocks and older external embedders.
  const g2w = addr => _memUtilsDll.guestToWasm(addr, exports, memory, imageBase);

  // Save state
  const savedEip = exports.get_eip();
  const savedEsp = exports.get_esp();
  const fsBase = exports.get_fs_base();
  const savedSeh = fsBase ? dv.getUint32(g2w(fsBase), true) : 0;
  const savedRegs = ['eax', 'ecx', 'edx', 'ebx', 'ebp', 'esi', 'edi']
    .filter(name => exports[`get_${name}`] && exports[`set_${name}`])
    .map(name => [name, exports[`get_${name}`]()]);
  const savedYield = exports.get_yield_reason ? exports.get_yield_reason() : 0;
  const savedYieldFlag = exports.get_yield_flag ? exports.get_yield_flag() : 0;
  const savedControl = ['handler_set_eip', 'steps']
    .filter(name => exports[`get_${name}`] && exports[`set_${name}`])
    .map(name => [name, exports[`get_${name}`]()]);
  let fault = null;

  let esp = savedEsp;
  // Push args in reverse order: lpReserved, fdwReason, hModule, ret=0.
  esp -= 4; dv.setUint32(g2w(esp), lpReserved, true);  // static != 0, dynamic = 0
  esp -= 4; dv.setUint32(g2w(esp), reason, true);
  esp -= 4; dv.setUint32(g2w(esp), loadAddr, true);    // hModule
  esp -= 4; dv.setUint32(g2w(esp), 0, true);           // return address = 0 (sentinel)
  exports.set_esp(esp);
  exports.set_eip(dllMain);
  if (options.strictReturn && exports.set_eax) exports.set_eax(0);
  if (exports.clear_yield) exports.clear_yield();

  if (log) log(`Calling DllMain at 0x${dllMain.toString(16)}...`);
  // Run up to 2M blocks per slice — DllMain should complete well within this.
  // A DLL initializer is allowed to call Sleep. The normal process scheduler
  // resumes that cooperative yield later, but callDllMain is deliberately
  // synchronous: restoring the caller's EIP/ESP while the initializer is only
  // half-finished abandons its stack frame and leaves the DLL corrupted. Treat
  // Sleep as a scheduling point here and immediately continue the initializer.
  // The host advances its guest clock by the requested interval first: old
  // DirectX DLLs calibrate RDTSC against GetTickCount around Sleep, and seeing
  // zero elapsed milliseconds sends their arithmetic through corrupt state.
  // The bounded count still catches a DLL that tries to sleep forever.
  try {
    let sleepYields = 0;
    let resumes = 0;
    for (;;) {
      exports.run(options.cooperative ? options.maxBlocks : maxBlocks);
      if (options.cooperative) {
        if (options.didRun) options.didRun();
        if (options.cancelled()) return { completed: false };
        if ((exports.get_eip() >>> 0) <= 2 ||
            (exports.get_yield_reason && exports.get_yield_reason() === 2)) break;
        const halt = exports.get_last_run_halt ? exports.get_last_run_halt() : 3;
        if (![1, 3, 4, 5].includes(halt)) break;
        yield { kind: 'schedule' };
        continue;
      }
      if (exports.get_yield_reason && [3, 5, 18].includes(exports.get_yield_reason() >>> 0)) {
        if (yield { kind: (exports.get_yield_reason() >>> 0) === 3 ? 'comDll' : 'loadLibrary' }) {
          if ((exports.get_yield_reason() >>> 0) === 2) break;
          continue;
        }
        break;
      }
      if ((exports.get_eip() >>> 0) <= 2 &&
          (!exports.get_yield_reason || (exports.get_yield_reason() >>> 0) !== 5)) break;
      const halt = exports.get_last_run_halt
        ? (exports.get_last_run_halt() | 0) : 3;
      const slept = halt === 3 && exports.get_sleep_yielded &&
        !!exports.get_sleep_yielded();
      if (slept) {
        sleepYields++;
        if (sleepYields > 64) {
          if (log) log('WARNING: DllMain exceeded 64 cooperative Sleep yields');
          break;
        }
        const sleepMs = exports.get_sleep_timeout ? exports.get_sleep_timeout() >>> 0 : 0;
        if (advanceGuestTime && sleepMs) advanceGuestTime(sleepMs);
        if (log) log(`DllMain resumed after cooperative Sleep (${sleepYields})`);
        continue;
      }
      // Not a Sleep. Halt 1 (block budget spent) and halt 3 (the host asked for
      // control -- a yield flag, or slot 0 consuming an input wake) are both
      // SCHEDULING signals, and neither means the initializer is finished. This
      // used to break out of the loop for them, which does precisely what the
      // comment above forbids: it restores the caller's EIP and ESP while
      // DllMain is mid-frame, so the DLL keeps whatever globals it had managed
      // to write and none of the ones it had not.
      //
      // That is how d3dxof.dll came to fail: its initializer was abandoned at
      // the SetEvent in its one-time-init, so the heap handle it stores next
      // stayed zero, DirectXFileCreate's HeapAlloc(hHeap=0) returned NULL, and
      // every D3DRM app reported D3DRMERR_BADFILE -- "Failed to load
      // sphere3.x", which reads as a missing or corrupt asset and is neither.
      // A half-initialized DLL fails far from here and never mentions DllMain.
      //
      // Halt 2 is EIP zero, already handled above. Halt 4 is a genuine blocking
      // wait and halt 5 a debug facility; resuming either would spin, so those
      // still stop and the caller's warning reports the code.
      if (halt !== 1 && halt !== 3) break;
      // A LoadLibraryA inside the initializer parks the guest at its thunk and
      // yields for the host to map the DLL. Resuming without servicing it
      // returns a garbage HMODULE to the DllMain that asked.
      resumes++;
      // A DLL initializer that cannot finish in 64 full slices of maxBlocks is
      // not merely unlucky with the scheduler, so the bound still catches a
      // runaway rather than hanging the loader.
      if (resumes > 64) {
        if (log) log(`WARNING: DllMain exceeded 64 resumes (last halt=${halt})`);
        break;
      }
    }
  } catch (e) {
    const crashEip = exports.get_eip();
    const crashEsp = exports.get_esp();
    const crashEax = exports.get_eax() >>> 0;
    // Check if DllMain actually succeeded — return to sentinel addr 0 causes
    // a trap when the decoder tries to execute at address 0/1. EAX=1 means
    // DLL_PROCESS_ATTACH returned TRUE.
    // The sentinel counts as a return only if RET consumed the complete
    // stdcall frame. A NULL jump, or ExitThread, can also leave EIP zero.
    if (options.strictReturn || !(crashEip === 0 && crashEsp === savedEsp)) {
      fault = e;
      if (log) log(`DllMain trapped: ${e.message}`);
      if (log) log(`  crash EIP=0x${crashEip.toString(16)} ESP=0x${crashEsp.toString(16)} EAX=0x${crashEax.toString(16)}`);
    }
  }

  const finalEip = exports.get_eip();
  const finalEsp = exports.get_esp();
  const returnValue = exports.get_eax() >>> 0;
  const exited = !!(exports.get_yield_reason && exports.get_yield_reason() === 2);
  const completed = !fault && !exited && finalEip === 0 && finalEsp === savedEsp &&
    (!options.strictReturn || (exports.get_last_run_halt?.() === 2 && !exports.get_yield_reason?.()));
  if (finalEip !== 0) {
    const yieldReason = exports.get_yield_reason ? (exports.get_yield_reason() >>> 0) : 0;
    // The halt code is the fact that says whether this is recoverable, so it
    // is printed with the rest: 1 budget exhausted, 2 EIP zero, 3 $yield_flag,
    // 4 blocking wait, 5 a debug facility (src/01-header.wat:1864). Without it
    // "did not return cleanly" names a symptom and no cause, and the two that
    // matter here look identical from outside -- a DLL that wanted one more
    // slice, and one that is genuinely stuck.
    const halt = exports.get_last_run_halt ? (exports.get_last_run_halt() | 0) : -1;
    if (log) log(`WARNING: DllMain did not return cleanly, EIP=0x${finalEip.toString(16)}`
      + ` yield=${yieldReason} halt=${halt}`);
  } else {
    if (log) log(`DllMain returned, EAX=0x${(exports.get_eax()>>>0).toString(16)}`);
  }

  // Restore ESP (DllMain is stdcall, it cleaned up the 12 bytes of args,
  // and RET popped the return address, so ESP should be back to savedEsp)
  // But just in case, restore it
  if (!exited && (!options.cooperative || completed)) {
    exports.set_esp(savedEsp);
    exports.set_eip(savedEip);
    for (const [name, value] of savedRegs) exports[`set_${name}`](value);
    for (const [name, value] of savedControl) exports[`set_${name}`](value);
    if (exports.set_yield_state) exports.set_yield_state(savedYield, savedYieldFlag);
    if (fsBase) dv.setUint32(g2w(fsBase), savedSeh, true);
  }
  return { completed, exited, returnValue, fault,
    eip: finalEip >>> 0, esp: finalEsp >>> 0 };
}

wrapper.text:
function callDllMain(exports, loadAddr, dllMain, log, options = {}) {
  const gate = requireDllCallbackGate(exports);
  try { return callDllMainOwned(exports, loadAddr, dllMain, log, options); } finally { gate.release(); }
}
